import csv
import io

_DIGITS = frozenset('0123456789')


def _field(row, key):
    value = row.get(key)
    return value if isinstance(value, str) else ''


def import_text(text, store, dry_run=False):
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}

    # Phase 1: trim, validate, and capture every row before touching the store.
    # This guarantees an invalid row (even a late one) raises ValueError with the
    # store left exactly as it was, per the README contract.
    planned = []
    for row in csv.DictReader(io.StringIO(text)):
        sku = _field(row, 'sku').strip()
        name = _field(row, 'name').strip()
        qty = _field(row, 'qty').strip()

        if not sku:
            raise ValueError('invalid row: sku must not be empty')
        if not name:
            raise ValueError('invalid row: name must not be empty')
        if not qty or not set(qty) <= _DIGITS:
            raise ValueError('invalid row: qty must be non-negative decimal digits')

        item = {'sku': sku, 'name': name, 'qty': int(qty)}
        planned.append((item, store.get(sku)))

    # Phase 2: compute the result and commit (normal import only).
    for item, before in planned:
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)

    return result

